// Cross-language conformance: values generated by the Python reference peer (contracts/test_vectors.json).
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:phone_transfer_pro/core/protocol/codec.dart';
import 'package:phone_transfer_pro/core/protocol/errors.dart';
import 'package:phone_transfer_pro/core/protocol/framing.dart';
import 'package:phone_transfer_pro/core/protocol/paths.dart';
import 'package:phone_transfer_pro/core/protocol/qr_payload.dart';

void main() {
  final v = jsonDecode(File('../contracts/test_vectors.json').readAsStringSync()) as Map<String, dynamic>;
  final sid = unb64u(v['sid']), fp = unb64u(v['fp']), nj = unb64u(v['nonceJ']), nh = unb64u(v['nonceH']);

  test('pairing proof, resume proof and SAS match the reference peer', () {
    expect(b64u(pairingProof(sid, fp, nj)), v['pairingProof']);
    expect(b64u(resumeProof(unb64u(v['resumeToken']), fp, nj)), v['resumeProof']);
    expect(sasCode(sid, fp, nj, nh), v['sas']);
  });

  test('QR payload from the reference peer parses', () {
    final qr = QrPayload.parse(v['qrUri'] as String, ignoreExpiry: true);
    expect(qr.sid, sid);
    expect(qr.fingerprint, fp);
    expect(qr.hostRole, 'receiver');
    expect(qr.endpoints, ['192.168.1.23:47321', '[fe80::1]:47321']);
    // Round trip keeps the same field set (no PII added).
    final again = QrPayload.parse(qr.toUri(), ignoreExpiry: true);
    expect(again.sid, sid);
  });

  test('expired QR is rejected', () {
    // Vector expires 2030-01-01; parse "after" that instant.
    expect(() => QrPayload.parse(v['qrUri'] as String, now: DateTime.utc(2031)),
        throwsA(isA<PtpException>().having((e) => e.code, 'code', PtpErrorCode.pairingExpired)));
  });

  test('path rules: NFC normalisation and rejections identical to reference', () {
    for (final item in (v['validPaths'] as List).cast<Map<String, dynamic>>()) {
      expect(validateRelativePath(item['in']), item['nfc']);
    }
    for (final bad in (v['invalidPaths'] as List)) {
      expect(() => validateRelativePath(bad),
          throwsA(isA<PtpException>().having((e) => e.code, 'code', PtpErrorCode.manifestInvalid)), reason: '$bad');
    }
  });

  test('data frame header layout matches reference bytes', () async {
    final expected = _hex(v['dataFrameHeaderHex'] as String);
    final out = _CollectSink();
    final w = FrameWriter(out);
    await w.data(7, 1 << 33, Uint8List.fromList(utf8.encode('abc')));
    expect(out.bytes, expected);
    final r = FrameReader(Stream.value(Uint8List.fromList(expected)));
    final f = await r.read(1 << 20) as DataFrame;
    expect([f.index, f.offset, utf8.decode(f.payload)], [7, 1 << 33, 'abc']);
  });
}

List<int> _hex(String s) => [for (var i = 0; i < s.length; i += 2) int.parse(s.substring(i, i + 2), radix: 16)];

class _CollectSink implements IOSink {
  final List<int> bytes = [];
  @override
  Encoding encoding = utf8;
  @override
  void add(List<int> data) => bytes.addAll(data);
  @override
  Future<void> flush() async {}
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}
